const SUBSYSTEM_LABELS:Record<SubsystemKey,string>={render:"RENDER · canvas",terrain:"Terrain / ground",streaming:"Map chunk streaming",entities:"Entities / vehicles",camera:"Camera / zoom",hud:"HUD / UI",collision:"Collision queries",enemyAi:"Enemy AI",audio:"Audio",save:"Save / snapshot"};
function emptySubsystemValues():SubsystemValues{return{render:0,terrain:0,streaming:0,entities:0,camera:0,hud:0,collision:0,enemyAi:0,audio:0,save:0};}
function emptySubsystemHistories():Record<SubsystemKey,number[]>{return{render:[],terrain:[],streaming:[],entities:[],camera:[],hud:[],collision:[],enemyAi:[],audio:[],save:[]};}
let activeSubsystemFrame:SubsystemValues|null=null;
let chunkLoadSequence=0;
const chunkLoadEventLog:Array<{sequence:number;timestamp:number;key:string;durationMs:number;drawCalls:number}>=[];
let peakPerfFrame:LatestPerfFrame|null=null;
let activeDrawCallCount=0,activeChunkBuildMs=0,activeChunkBuildSteps=0,activeChunkBuildCompletions=0,activeChunkQueuePeak=0,activeChunksQueuedThisFrame=0,activeVisibleChunkBlits=0,groundCanvasAllocations=0,groundCanvasReuses=0,activeAudioVoices=0,activeLightingMs=0;
const DRAW_CALL_METHODS=["drawImage","fillRect","strokeRect","clearRect","fill","stroke","fillText","strokeText","putImageData"] as const;
const instrumentedCanvasContexts=new WeakSet<CanvasRenderingContext2D>();
function instrumentCanvasDrawCalls(ctx:CanvasRenderingContext2D):CanvasRenderingContext2D{if(instrumentedCanvasContexts.has(ctx))return ctx;instrumentedCanvasContexts.add(ctx);const target=ctx as unknown as Record<string,unknown>;for(const method of DRAW_CALL_METHODS){const original=target[method];if(typeof original!=="function")continue;target[method]=(...args:unknown[])=>{activeDrawCallCount+=1;return Reflect.apply(original,ctx,args);};}return ctx;}
function noteChunkLoad(key:string,durationMs:number,drawCalls:number):void{chunkLoadSequence+=1;chunkLoadEventLog.push({sequence:chunkLoadSequence,timestamp:Date.now(),key,durationMs,drawCalls});if(chunkLoadEventLog.length>5000)chunkLoadEventLog.splice(0,chunkLoadEventLog.length-5000);}
function recordSubsystem(key:SubsystemKey,elapsed:number):void{if(activeSubsystemFrame)activeSubsystemFrame[key]+=Math.max(0,elapsed);}
function measureSubsystem<T>(key:SubsystemKey,work:()=>T):T{const started=performance.now();try{return work();}finally{recordSubsystem(key,performance.now()-started);}}

