function applyRadialDeadZone(input:Vec):Vec {
  const magnitude=Math.min(1,Math.hypot(input.x,input.y));
  if(magnitude<=JOYSTICK_DEAD_ZONE)return{x:0,y:0};
  const scaledMagnitude=(magnitude-JOYSTICK_DEAD_ZONE)/(1-JOYSTICK_DEAD_ZONE),scale=scaledMagnitude/magnitude;
  return{x:input.x*scale,y:input.y*scale};
}
