function emitNoiseAt(world:World,now:number,radius:number,x:number,y:number):number{let drawn=0;for(const enemy of world.enemies){if(enemy.hp<=0||Math.hypot(enemy.x-x,enemy.y-y)>radius)continue;enemy.aggro=Math.max(enemy.aggro,4.5);if(enemy.kind==="witch")enemy.state="witchChase";enemy.lastSeenX=x;enemy.lastSeenY=y;drawn+=1;}if(drawn>0){world.noiseUntil=Math.max(world.noiseUntil,now+1250);world.noiseDrawn=drawn;world.noiseRadius=radius;world.noiseX=x;world.noiseY=y;}return drawn;}
