function mapTerrainClass(region: Region): string {
  if (region.id === 14 || region.id === 15 || region.id === 16) return "terrain-city";
  if (region.id === 13) return "terrain-frontier";
  if (region.id === 12) return "terrain-frost";
  if (region.volcanic || region.id === 7) return "terrain-lava";
  if (region.id === 3) return "terrain-water";
  if (region.id === 8 || region.id === 11) return "terrain-mire";
  if (region.id === 9) return "terrain-starfall";
  if (region.village) return "terrain-village";
  return region.id === 4 ? "terrain-bramble" : "terrain-forest";
}
