function pointInPolygon(x:number,y:number,points:ReadonlyArray<readonly [number,number]>):boolean {
  let inside=false;
  for(let i=0,j=points.length-1;i<points.length;j=i,i+=1){const current=points[i],previous=points[j];if(!current||!previous)continue;const [xi,yi]=current,[xj,yj]=previous;const crosses=(yi>y)!==(yj>y)&&x<(xj-xi)*(y-yi)/(yj-yi)+xi;if(crosses)inside=!inside;}
  return inside;
}
