  if (rareId === "mirestride") return { ...save, armorName: item.name, armorDefense: Math.max(save.armorDefense, 14), moveSpeed: Math.max(save.moveSpeed, .18), items };
  if (rareId === "regentsSeal") return { ...save, armorName: item.name, armorDefense: Math.max(save.armorDefense, 34), maxHp: Math.max(save.maxHp, 210), hp: Math.max(save.hp, 210), thorns: Math.max(save.thorns, .5), items };
  if (rareId === "sunwraithsVeil") return { ...save, armorName: item.name, armorDefense: Math.max(save.armorDefense, 24), sunwraithVeilOwned: true, items };
  if (rareId === "harvestersCowl") return { ...save, armorName: item.name, armorDefense: Math.max(save.armorDefense, 22), moveSpeed: Math.max(save.moveSpeed, .14), items };
  if (rareId === "heartOfEmber") return { ...save, weaponName: item.name, weaponDamage: Math.max(save.weaponDamage, 72), critChance: Math.max(save.critChance, .3), maxHp: Math.max(save.maxHp, 240), hp: Math.max(save.hp, 240), rarity: "Relic", items };
