function mysteryBoxLocation(save:PersistedSave):MysteryBoxLocation{return MYSTERY_BOX_LOCATIONS[Math.max(0,Math.min(MYSTERY_BOX_LOCATIONS.length-1,save.boxLocation??0))]??MYSTERY_BOX_LOCATIONS[0]??{name:"Greyhaven",x:2860,y:3300};}
function chooseMysteryReward(save:PersistedSave):MysteryReward{const recent=new Set((save.boxPoolState??[]).slice(-3)),available=MYSTERY_REWARDS.filter(reward=>!recent.has(reward.name)),pool=available.length?available:MYSTERY_REWARDS,total=pool.reduce((sum,reward)=>sum+reward.weight,0);let roll=Math.random()*total;for(const reward of pool){roll-=reward.weight;if(roll<=0)return reward;}return pool[0]??MYSTERY_REWARDS[0]??{kind:"key",id:"iron",name:"Iron Key",rarity:"Uncommon",weight:1};}
function grantMysteryReward(save:PersistedSave,reward:MysteryReward):PersistedSave{
  if(reward.kind==="gun")return addGunToSave(save,GUNS[reward.id]);
  if(reward.kind==="relic")return applyRareLoot(save,reward.id);
  if(reward.kind==="throwable")return reward.id==="pipeBomb"?{...save,pipeBombs:Math.min(99,save.pipeBombs+2)}:reward.id==="molotov"?{...save,molotovs:Math.min(99,save.molotovs+2)}:{...save,bileJars:Math.min(99,save.bileJars+2)};
  if(reward.kind==="key")return reward.id==="iron"?{...save,ironKeys:Math.min(99,save.ironKeys+1)}:reward.id==="gold"?{...save,goldKeys:Math.min(99,save.goldKeys+1)}:{...save,ancientKeys:Math.min(99,save.ancientKeys+1)};
  return {...save,items:[...new Set([...save.items,reward.name])].slice(-60)};
}

