  const x=save.harvesterState===1&&save.harvesterX>0?save.harvesterX:waypoint.x;
  const y=save.harvesterState===1&&save.harvesterY>0?save.harvesterY:waypoint.y;
  const zone=regionAtPoint(x,y)?.id??waypoint.zone,enemy=makeEnemy("harvester",HARVESTER_ID,zone,x,y);
