    if(inside.w>=330){ctx.strokeStyle=active.ruined?"rgba(140,136,128,.7)":"rgba(210,190,150,.72)";ctx.lineWidth=9;ctx.beginPath();ctx.moveTo(left+18,inside.y);ctx.lineTo(inside.x-38,inside.y);ctx.moveTo(inside.x+38,inside.y);ctx.lineTo(right-18,inside.y);ctx.stroke();}
    ctx.fillStyle=active.ruined?"#5f574b":"#8a603a";ctx.fillRect(left+28,top+30,72,38);ctx.fillStyle=active.ruined?"#777169":"#b18452";ctx.fillRect(left+34,top+36,60,8);
    ctx.fillStyle=active.ruined?"#3d3b37":"#56402d";ctx.fillRect(right-92,top+26,58,76);ctx.strokeStyle=active.ruined?"#777169":"#9b7650";ctx.lineWidth=4;for(let shelf=0;shelf<3;shelf+=1){ctx.beginPath();ctx.moveTo(right-88,top+42+shelf*22);ctx.lineTo(right-38,top+42+shelf*22);ctx.stroke();}
