    if(!looted){const chestX=inside.x+(inside.w>300?inside.w*.28:0),chestY=inside.y-inside.h*.2;ctx.strokeStyle=`rgba(255,209,102,${.42+Math.sin(time/180)*.12})`;ctx.lineWidth=3;ctx.setLineDash([8,7]);ctx.beginPath();ctx.arc(chestX,chestY,55,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle="#ffe39a";ctx.font="900 9px system-ui";ctx.textAlign="center";ctx.fillText("SEARCH",chestX,chestY-61);}
