function formatRunTime(start:string):string{const total=Math.max(0,Math.floor((Date.now()-new Date(start).getTime())/1000));return `${Math.floor(total/60)}:${(total%60).toString().padStart(2,"0")}`;}
function formatAge(iso:string):string{const minutes=Math.max(0,Math.round((Date.now()-new Date(iso).getTime())/60000));if(minutes<1)return"just now";if(minutes<60)return`${minutes}m ago`;const hours=Math.round(minutes/60);return hours<24?`${hours}h ago`:`${Math.round(hours/24)}d ago`;}

