  {mode==="playing"&&profilerMode==="idle"&&<button type="button" className="profiler-idle" aria-label="Open frame profiler" onClick={()=>updateProfilerMode("compact")}><span>FPS</span><b>{profiler.samples?Math.round(profiler.fps):"—"}</b></button>}
  {mode==="playing"&&profilerMode!=="idle"&&<aside className={`profiler-overlay ${profilerMode}`} aria-label={`Frame profiler. ${Math.round(profiler.fps)} frames per second, ${profiler.average.toFixed(1)} millisecond average frame time, ${profiler.p95.toFixed(1)} millisecond p95, ${profiler.worst.toFixed(1)} millisecond worst frame.`}><button type="button" className="profiler-close" aria-label="Hide frame profiler" onClick={()=>updateProfilerMode("idle")}>×</button><button type="button" className="profiler-readout" aria-label={profilerMode==="compact"?"Expand frame-time history":"Collapse frame-time history"} onClick={()=>updateProfilerMode(profilerMode==="compact"?"expanded":"compact")}><div className="profiler-stats"><span><small>FPS</small><strong>{profiler.samples?Math.round(profiler.fps):"—"}</strong></span><span><small>AVG</small><strong>{profiler.average.toFixed(1)}<i> ms</i></strong></span><span><small>P95</small><strong>{profiler.p95.toFixed(1)}<i> ms</i></strong></span><span><small>WORST</small><strong>{profiler.worst.toFixed(1)}<i> ms</i></strong></span></div></button><div className="profiler-live" aria-label="Live performance counters"><span><small>DRAW</small><b>{profiler.drawCalls}</b></span><span><small>CHUNK/S</small><b>{profiler.chunkRebuildsPerSec}</b></span><span><small>CORPSE</small><b>{profiler.corpses}</b></span><span><small>PART</small><b>{profiler.activeSparks}</b></span><span><small>DECAL</small><b>{profiler.decals}</b></span><span><small>LOOT</small><b>{profiler.totalPickups}</b></span></div><button type="button" className={`minimal-mode-toggle${minimalMode?" active":""}`} aria-label={`${minimalMode?"Disable":"Enable"} minimal performance mode`} aria-pressed={minimalMode} onClick={toggleMinimalMode}><span>MINIMAL MODE</span><b>{minimalMode?"ON":"OFF"}</b></button><div className="effect-switches" aria-label="Effect kill switches">{EFFECT_OPTIONS.map(option=><button type="button" key={option.key} className={effectFlags[option.key]?"on":"off"} aria-label={`${option.label} ${effectFlags[option.key]?"on":"off"}. Tap to toggle.`} aria-pressed={effectFlags[option.key]} onClick={()=>toggleEffect(option.key)}><span>{option.label}</span><b>{effectFlags[option.key]?"ON":"OFF"}</b></button>)}</div>{profilerMode==="expanded"&&<div className="profiler-history"><div><span>300-frame history</span><b>{profilerGraphCeiling} ms</b></div><svg viewBox="0 0 240 72" preserveAspectRatio="none" aria-hidden="true"><line className="profiler-guide sixty" x1="0" y1={70-16.7/profilerGraphCeiling*66} x2="240" y2={70-16.7/profilerGraphCeiling*66}/><line className="profiler-guide thirty" x1="0" y1={70-33.3/profilerGraphCeiling*66} x2="240" y2={70-33.3/profilerGraphCeiling*66}/><polyline points={profilerGraphPoints}/></svg><div className="profiler-subsystems" aria-label="Average subsystem frame times">{profilerSubsystems.map(key=><div key={key} className={key===profilerHotspot?"hotspot":""}><span>{SUBSYSTEM_LABELS[key]}</span><b>{profiler.subsystems[key].toFixed(1)} ms</b></div>)}</div><div className="profiler-peak" aria-label="Worst single frame since reset"><div className="profiler-peak-head"><span>WORST FRAME</span><b>{peakFrame?`${peakFrame.frameMs.toFixed(1)} ms`:"—"}</b><i>{peakFrame&&peakFrame.frameMs>0?`${Math.round(1000/peakFrame.frameMs)} fps`:""}</i><button type="button" aria-label="Reset worst frame capture" onClick={()=>{peakPerfFrame=null;setPeakFrame(null);}}>RESET</button></div>{peakFrame&&<>{[...SUBSYSTEM_KEYS].sort((a,b)=>peakFrame.subsystems[b]-peakFrame.subsystems[a]).filter(key=>peakFrame.subsystems[key]>=.05).map(key=><div key={key}><span>{SUBSYSTEM_LABELS[key]}</span><b>{peakFrame.subsystems[key].toFixed(1)} ms</b></div>)}<small>speed {Math.round(peakFrame.vehicleSpeed)} · draw {peakFrame.drawCalls} · chunks {peakFrame.groundChunksCached} cached / queue {peakFrame.chunkQueueDepth} (peak {peakFrame.chunkQueuePeak}) / build {peakFrame.chunkBuildMs.toFixed(1)} ms · canvas {peakFrame.chunkCanvasAllocations} new / {peakFrame.chunkCanvasReuses} reused / pool {peakFrame.chunkPoolSize} · enemies {peakFrame.totalEnemies}</small></>}</div><small>{profiler.activeEnemies} active / {profiler.visibleEnemies} visible / {profiler.totalEnemies} total enemies · residue {profiler.totalPickups} pickups / {profiler.activeProjectiles} shots / {profiler.activeSparks} particles / {profiler.corpses} corpses / {profiler.decals} decals / {profiler.activeDamageNumbers} numbers / {profiler.activeAudioVoices} voices · terrain {profiler.chunkRebuildsPerSec}/s / {profiler.groundChunksCached} chunks / {profiler.groundCacheMiB.toFixed(1)} MiB / {profiler.groundQueueSlots} queue slots · {profiler.drawCalls} draw calls · chunk {profiler.chunkBuildMs.toFixed(2)} ms / {profiler.chunkBuildSteps} steps / {profiler.chunkBuildCompletions} finished · queue {profiler.chunkQueueDepth} ({profiler.chunkQueuePeak} peak, +{profiler.chunksQueuedThisFrame}) · {profiler.visibleChunks} visible · {Math.round(renderScale*100)}% resolution</small><div className="profiler-recording"><button type="button" className={recordingActive?"recording":""} aria-label={recordingActive?"Stop and save profiler recording":"Start profiler recording"} onClick={()=>recordingActive?void finishProfilerRecording():startProfilerRecording()}><i/>{recordingActive?`STOP · ${recordingSampleCount}`:"RECORD"}</button><span>{recordingStatus}</span></div><div className="profiler-recordings" aria-label="Saved profiler recordings"><strong>SAVED RUNS</strong>{recordingsQuery.data?.recordings.length?recordingsQuery.data.recordings.map((recording:PerfRecordingSummary)=><button type="button" key={recording.id} className={recording.id===selectedRecordingId?"selected":""} aria-label={`Open profiler recording from ${new Date(recording.startedAt).toLocaleString()}`} onClick={()=>setSelectedRecordingId(recording.id)}><span>{new Date(recording.startedAt).toLocaleTimeString([],{hour:"numeric",minute:"2-digit",second:"2-digit"})}–{new Date(recording.stoppedAt).toLocaleTimeString([],{hour:"numeric",minute:"2-digit",second:"2-digit"})}</span><b>{recording.averageFps.toFixed(0)} FPS · {recording.stallCount50} stalls · {recording.chunkLoadCount} chunks</b></button>):<small>{recordingsQuery.isPending?"Loading recordings…":recordingsQuery.data?.message??"No saved recordings yet"}</small>}{selectedPerfRecording&&<div className="profiler-recording-detail"><span>{selectedPerfRecording.sampleCount} samples · {selectedPerfRecording.averageFps.toFixed(0)} FPS · {selectedPerfRecording.averageFrameMs.toFixed(1)} ms avg</span><span>P95 {selectedPerfRecording.p95FrameMs.toFixed(1)} ms · worst frame {selectedPerfRecording.worstFrameMs.toFixed(1)} ms</span><b>Worst jank {selectedPerfRecording.worstJankMs.toFixed(1)} ms · {selectedPerfRecording.stallCount50} over 50 ms · {selectedPerfRecording.jankCount100} over 100 ms</b>{baselinePerfRecording&&selectedPerfRecording.id!==7&&<span>Before #7: {baselinePerfRecording.stallCount50} over 50 ms / {baselinePerfRecording.jankCount100} over 100 ms · after #{selectedPerfRecording.id}: {selectedPerfRecording.stallCount50} / {selectedPerfRecording.jankCount100}</span>}<span>Render {selectedPerfRecording.averageRenderMs.toFixed(1)} ms avg / {selectedPerfRecording.p95RenderMs.toFixed(1)} ms p95 · {selectedPerfRecording.averageDrawCalls.toFixed(0)} avg / {selectedPerfRecording.maxDrawCalls} max draws</span><span>Chunk work {selectedPerfRecording.averageChunkBuildMs.toFixed(2)} ms avg · {selectedPerfRecording.hitchWithChunkBuildCount}/{selectedPerfRecording.chunkBuildFrameCount} sampled build frames exceeded 25 ms</span><span>{selectedPerfRecording.maxChunkQueueDepth===null?"Queue / visible chunks not recorded in this legacy run":<>Queue {selectedPerfRecording.maxChunkQueueDepth} max ({selectedPerfRecording.maxChunkQueuePeak} frame peak) · +{selectedPerfRecording.maxChunksQueuedThisFrame} max queued in a frame · {(selectedPerfRecording.averageVisibleChunks??0).toFixed(1)} avg / {selectedPerfRecording.maxVisibleChunks} max visible</>}</span><span>{selectedPerfRecording.chunkLoadCount} chunks finished · canvases {selectedPerfRecording.chunkCanvasAllocations} allocated / {selectedPerfRecording.chunkCanvasReuses} reused · {selectedPerfRecording.hotspot} hotspot</span></div>}</div></div>}</aside>}
  {mode==="playing"&&<><button type="button" className="world-map" aria-label={`Open world map. Current location ${mapRegionName}`} onClick={()=>changeMode("map")}><div className="map-field">{REGIONS.map(r=><MiniMapBiome key={r.id} region={r} left={(r.x-mapX)/MAP_VIEW_W*100} top={(r.y-mapY)/MAP_VIEW_H*100} width={Math.max(16,r.radius*2.18/MAP_VIEW_W*100)} height={Math.max(12,r.radius*2.18/MAP_VIEW_H*100)} current={r.id===mapRegion?.id} cleared={worldRef.current.zoneCleared.has(r.id)}/>)}<span className="map-viewport" style={{left:`${(worldRef.current.camera.x-mapX)/MAP_VIEW_W*100}%`,top:`${(worldRef.current.camera.y-mapY)/MAP_VIEW_H*100}%`,width:`${VIEW_W/worldRef.current.camera.zoom/MAP_VIEW_W*100}%`,height:`${VIEW_H/worldRef.current.camera.zoom/MAP_VIEW_H*100}%`}}/><svg className="map-fog" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><defs><filter id="mapFogFeather" x="-25%" y="-25%" width="150%" height="150%"><feGaussianBlur stdDeviation="3.2"/></filter><filter id="mapFogClouds" x="-15%" y="-15%" width="130%" height="130%"><feTurbulence type="fractalNoise" baseFrequency=".055" numOctaves="3" seed="7" result="noise"/><feDisplacementMap in="SourceGraphic" in2="noise" scale="5" xChannelSelector="R" yChannelSelector="B"/></filter><mask id="mapFogMask" maskUnits="userSpaceOnUse" x="0" y="0" width="100" height="100"><rect width="100" height="100" fill="white"/><g filter="url(#mapFogFeather)">{fogReveal.map(point=><ellipse key={point.key} cx={point.x} cy={point.y} rx={point.rx} ry={point.ry} fill="black"/>)}</g></mask></defs><g mask="url(#mapFogMask)"><rect className="fog-base" width="100" height="100"/><rect className="fog-cloud" x="-4" y="-4" width="108" height="108" filter="url(#mapFogClouds)"/></g></svg>{DUNGEONS.filter(dungeon=>dungeon.id!=="sewer").map(dungeon=><i key={dungeon.id} className="map-dungeon" aria-label={`${dungeon.name} entrance`} style={{left:`${(dungeon.entrance.x-mapX)/MAP_VIEW_W*100}%`,top:`${(dungeon.entrance.y-mapY)/MAP_VIEW_H*100}%`,borderColor:dungeon.color}}/>)}{SEWER_ENTRANCES.map((entrance,index)=><i key={`sewer-${index}`} className="map-dungeon sewer" aria-label={`${entrance.label} entrance`} style={{left:`${(entrance.x-mapX)/MAP_VIEW_W*100}%`,top:`${(entrance.y-mapY)/MAP_VIEW_H*100}%`,borderColor:"#9bb579"}}/>)}{OUTPOSTS.map(outpost=><i key={outpost.id} className={`map-outpost ${baseState(saveRef.current,outpost.id).claimed?"claimed":""}`} aria-label={`${outpost.name}${baseState(saveRef.current,outpost.id).claimed?", claimed":""}`} style={{left:`${(outpost.x-mapX)/MAP_VIEW_W*100}%`,top:`${(outpost.y-mapY)/MAP_VIEW_H*100}%`,borderColor:outpost.color}}/>)}{[{name:"Greyhaven",...FRONTIER_CENTER},{name:"Old Greyhaven",...RUINED_CITY_CENTER},{name:"Deadlight Mall",...MALL_CENTER},{name:"Saint Mercy Infirmary",...HOSPITAL_CENTER}].map(city=><span key={city.name} className="map-city-pin" style={{left:`${(city.x-mapX)/MAP_VIEW_W*100}%`,top:`${(city.y-mapY)/MAP_VIEW_H*100}%`}}>{city.name}</span>)}<i className="map-boxkeeper" aria-label={`Mystery Box at ${boxLocation.name}`} style={{left:`${(boxLocation.x-mapX)/MAP_VIEW_W*100}%`,top:`${(boxLocation.y-mapY)/MAP_VIEW_H*100}%`}}>?</i><i className="map-yarrow" aria-label={`Doc Yarrow at ${docLocation.name}`} style={{left:`${(docLocation.x-mapX)/MAP_VIEW_W*100}%`,top:`${(docLocation.y-mapY)/MAP_VIEW_H*100}%`}}>Y</i>{(()=>{const h=worldRef.current.enemies.find(enemy=>enemy.kind==="harvester"&&enemy.hp>0);return h?<i className="map-harvester-marker" aria-label="The Harvester skull marker" style={{left:`${(h.x-mapX)/MAP_VIEW_W*100}%`,top:`${(h.y-mapY)/MAP_VIEW_H*100}%`}}>☠</i>:null;})()}<b style={{left:`${(hud.x-mapX)/MAP_VIEW_W*100}%`,top:`${(hud.y-mapY)/MAP_VIEW_H*100}%`}}/>{activeInterior&&<span className="map-interior">INSIDE</span>}{worldRef.current.dungeon==="sewer"&&<><i className="map-dungeon sewer" aria-label="Sewer climb exit" style={{left:`${(DUNGEON_ENTRY.x-mapX)/MAP_VIEW_W*100}%`,top:`${(DUNGEON_ENTRY.y-mapY)/MAP_VIEW_H*100}%`,borderColor:"#cfe7a0"}}/><i className="map-dungeon sewer boss" aria-label="Deep Sump boss chamber" style={{left:`${(DUNGEON_BOSS.x-mapX)/MAP_VIEW_W*100}%`,top:`${(DUNGEON_BOSS.y-mapY)/MAP_VIEW_H*100}%`,borderColor:"#d6c15b"}}/><span className="map-interior">UNDERGROUND</span></>}<small className={`map-region-name ${mapRegion?"":"wilderness"}`}>{mapRegionName}</small></div></button>{hud.dogAdopted&&<div className={`dog-hud ${hud.dogStatus}`} aria-label={`Companion level ${hud.dogLevel}, health ${Math.round(hud.dogHp)} of ${hud.dogMaxHp}, ${hud.dogStatus}`}><div className="dog-hud-head"><span>COMPANION</span><b>LV {hud.dogLevel}</b></div><div className="dog-hud-row"><i className="dog-mark"/><div><span style={{width:`${Math.max(0,hud.dogHp/hud.dogMaxHp*100)}%`}}/></div><strong>{hud.dogStatus==="down"?"RECOVERING":hud.dogStatus.toUpperCase()}</strong></div></div>}{effectFlags.vehicles&&(hud.driving||hud.nearVehicle)&&<div className={`vehicle-hud ${hud.driving?"driving":"parked"}`} aria-label={`${hud.truckName} fuel ${Math.round(hud.truckFuel)} percent, health ${Math.round(hud.truckHp)} of ${hud.truckMaxHp}`}><div className="vehicle-hud-title"><strong>{hud.truckName.toUpperCase()}</strong><span>{hud.driving?`${Math.round(hud.truckSpeed)} SPD`:hud.truckHp<=0?"WRECKED":hud.truckName==="Mustang"&&!saveRef.current.vehicleKeyOwned?"LOCKED":hud.truckOwned?"OWNED":"UNCLAIMED"}</span></div><div className="vehicle-meter-row"><span>FUEL</span><div><i style={{width:`${hud.truckFuel}%`}}/></div><b>{Math.round(hud.truckFuel)}%</b></div><div className="vehicle-meter-row hp"><span>HP</span><div><i style={{width:`${hud.truckHp/hud.truckMaxHp*100}%`}}/></div><b>{Math.round(hud.truckHp)}</b></div>{hud.driving&&<div className={`vehicle-drive-state ${hud.truckSpeed>145?"ram-ready":""}`}><span>{hud.truckSpeed>145?"RAM READY":"JOYSTICK TO DRIVE"}</span><small>{hud.truckSpeed>145?"Hit zombies head-on":"Build speed to ram"}</small></div>}<button className="vehicle-cargo-button" aria-label={`Open ${hud.truckName} inventory, ${hud.truckCargo} of 4 slots used`} onClick={openVehicleStorage}><span>CARGO</span><b>{hud.truckCargo}/4</b><div>{Array.from({length:4},(_,index)=><i key={index} className={index<hud.truckCargo?"filled":""}/>)}</div></button></div>}{(hud.bloodMoonWarning||hud.bloodMoonActive)&&<div className={`blood-moon-warning ${hud.bloodMoonActive?"active":"dusk"}`} role="status"><span>{hud.bloodMoonActive?`BLOOD MOON ${hud.bloodMoonEventNumber}`:"BLOOD MOON AT NIGHTFALL"}</span><strong>{hud.bloodMoonActive?`WAVE ${Math.max(1,hud.bloodMoonWave)}/${hud.bloodMoonTotalWaves} · ${hud.bloodMoonEnemies} REMAIN`:`PREPARE · EVERY ${bloodMoonInterval} NIGHTS`}</strong></div>}{hud.raidText&&<div className="raid-warning" role="status"><span>BASE RAID</span><strong>{hud.raidText}</strong></div>}{hud.barricadeLabel&&<div className="barricade-integrity" role="status" aria-label={`${hud.barricadeLabel} barricade integrity ${hud.barricadeHp} of ${hud.barricadeMaxHp}`}><span>BOARDS</span><div><i style={{width:`${hud.barricadeMaxHp?hud.barricadeHp/hud.barricadeMaxHp*100:0}%`}}/></div><strong>{Math.round(hud.barricadeMaxHp?hud.barricadeHp/hud.barricadeMaxHp*100:0)}%</strong></div>}{hud.bossMaxHp>0&&activeBoss&&<div className="boss-bar"><strong>{(worldRef.current.dungeon?dungeonById(worldRef.current.dungeon)?.bossName:bossDisplayName(activeBoss))?.toUpperCase()}</strong><div><span style={{width:`${Math.max(0,hud.bossHp/hud.bossMaxHp*100)}%`}}/></div></div>}<div className="objective-panel"><span>{activeInterior?activeInterior.label:worldRef.current.dungeon?dungeonById(worldRef.current.dungeon)?.name:region.name}</span><strong>{activeInterior?`Inside · search the rooms · ${hud.enemies} ${hud.enemies===1?"threat":"threats"}`:worldRef.current.dungeon?(saveRef.current.dungeonBossesDefeated.includes(worldRef.current.dungeon)?(worldRef.current.dungeon==="sewer"?`Drain caches ${saveRef.current.sewerLootedCacheIds.length}/3 · exit remains open`:"Claim the gold chest · exit remains open"):activeBoss?`Defeat ${dungeonById(worldRef.current.dungeon)?.bossName??"the dungeon boss"}`:`Clear the chambers · ${hud.enemies} threats remain`):region.village?"Talk · trade · rest":worldRef.current.zoneCleared.has(hud.zone)?"Explore or claim the relic":activeBoss?`Defeat ${bossDisplayName(activeBoss)}`:`Hunt ${hud.enemies} ${hud.enemies===1?"threat":"threats"}`}</strong></div>{saveRef.current.origin==="farmhouse"&&!saveRef.current.farmhouseRewardClaimed&&<div className="quest-panel first-night-objective" aria-label="First Night survivor objective"><div className="quest-title"><span>FIRST NIGHT</span><strong>{saveRef.current.farmhouseIntroStage===0?"1/3":"2/3"}</strong></div><em>{saveRef.current.farmhouseIntroStage===0?"Wake at dusk · take the pipe wrench from the workbench":"Fend off the zombie pack at the porch · reward 2 potions + 60 gold"}</em></div>}{saveRef.current.mainStoryState!=="complete"&&<div className="quest-panel main-story-quest" aria-label={`Main quest ${mainStoryTitle(saveRef.current)}. ${mainStoryObjective(saveRef.current)}`}><div className="quest-title"><span>MAIN STORY · {mainStoryTitle(saveRef.current)}</span><strong>{saveRef.current.mainStoryState==="active"?`${Math.min(5,saveRef.current.veilTruthStage)}/5`:"0/5"}</strong></div><em>{mainStoryObjective(saveRef.current)}</em></div>}{saveRef.current.questState==="active"&&<div className="quest-panel" aria-label={`Quest The Ember Wastes Calling. Wayfire crossings ${questCounts.travel} of 2. Relic-bearers ${questCounts.elites} of 5. Ash Tyrant ${questCounts.tyrant} of 1.`}><div className="quest-title"><span>THE EMBER WASTES CALLING</span><strong>{questProgress}/{EMBER_QUEST_TOTAL}</strong></div><div className="quest-objectives"><small className={questCounts.travel===2?"done":""}>Wayfires <b>{questCounts.travel}/2</b></small><small className={questCounts.elites===5?"done":""}>Relic-bearers <b>{questCounts.elites}/5</b></small><small className={questCounts.tyrant===1?"done":""}>Ash Tyrant <b>{questCounts.tyrant}/1</b></small></div><em>{emberQuestNext(saveRef.current)}</em></div>}{saveRef.current.frontierQuestState==="active"&&<div className="quest-panel frontier-quest" style={{top:saveRef.current.questState==="active"?"25%":"11.5%"}} aria-label={`Quest Clear the Market Road. City zombies ${frontierQuestProgress(saveRef.current)} of ${FRONTIER_QUEST_IDS.length}.`}><div className="quest-title"><span>CLEAR THE MARKET ROAD</span><strong>{frontierQuestProgress(saveRef.current)}/{FRONTIER_QUEST_IDS.length}</strong></div><em>{frontierQuestProgress(saveRef.current)>=FRONTIER_QUEST_IDS.length?"Report back to Marshal Rowan":"Hunt the marked city dead in Old Greyhaven"}</em></div>}{npcQuestState(saveRef.current,STREET_SALVAGE_QUEST_ID)==="active"&&<div className="quest-panel street-quest" style={{top:saveRef.current.questState==="active"&&saveRef.current.frontierQuestState==="active"?"38.5%":saveRef.current.questState==="active"||saveRef.current.frontierQuestState==="active"?"25%":"11.5%"}} aria-label={`Quest Street Salvage. Caches looted ${streetSalvageProgress(saveRef.current)} of ${STREET_SALVAGE_IDS.length}.`}><div className="quest-title"><span>STREET SALVAGE</span><strong>{streetSalvageProgress(saveRef.current)}/{STREET_SALVAGE_IDS.length}</strong></div><em>{streetSalvageProgress(saveRef.current)>=STREET_SALVAGE_IDS.length?"Return to Bria Stone in Greyhaven":"Loot the pharmacy, transit lockers, and records vault"}</em></div>}{saveRef.current.wardRoundsStage>0&&saveRef.current.wardRoundsStage<4&&<div className="quest-panel ward-rounds-quest" style={{top:`${11.5+13.5*[saveRef.current.questState==="active",saveRef.current.frontierQuestState==="active",npcQuestState(saveRef.current,STREET_SALVAGE_QUEST_ID)==="active"].filter(Boolean).length}%`}} aria-label={`Quest Ward Rounds. Stage ${saveRef.current.wardRoundsStage} of 3. ${wardRoundsObjective(saveRef.current)}`}><div className="quest-title"><span>WARD ROUNDS</span><strong>{Math.max(0,saveRef.current.wardRoundsStage-1)}/3</strong></div><em>{wardRoundsObjective(saveRef.current)}</em></div>}<button type="button" className={`throwable-quick ${throwArmed?"armed":""}`} aria-label={`${throwArmed?"Cancel":"Aim"} ${THROWABLE_LABELS[hud.selectedThrowable]}. ${throwableCount(saveRef.current,hud.selectedThrowable)} remaining`} aria-pressed={throwArmed} onClick={armThrowable}><span>{hud.selectedThrowable==="pipeBomb"?"●":hud.selectedThrowable==="molotov"?"◒":"◉"}</span><b>{throwArmed?"TAP TARGET":THROWABLE_LABELS[hud.selectedThrowable]}</b><small>{throwableCount(saveRef.current,hud.selectedThrowable)}</small></button><div className="controls" aria-label={controlScheme==="joystick"?"Touch controls":"Keyboard and action controls"}>{controlScheme==="joystick"&&<div ref={joystickRef} className="joystick" role="group" aria-label="Movement joystick" onPointerDown={joyDown} onPointerMove={joyMove} onPointerUp={joyUp} onPointerCancel={joyUp}><div className="joystick-ring"/><div className="joystick-knob" style={{transform:`translate(${joystick.x}px,${joystick.y}px)`}}/></div>}<div className="action-stack">
  <div className="action-slot vehicle-slot">{effectFlags.vehicles&&(hud.driving||hud.nearVehicle)&&<button className="vehicle-button" aria-label={hud.driving?`Exit ${hud.truckName}`:hud.truckName==="Mustang"&&!saveRef.current.vehicleKeyOwned?"Mustang locked, needs a key — search buildings":hud.truckHp<=0?`Repair ${hud.truckName} for 50 gold`:hud.truckFuel<=0?`${hud.truckName} is out of fuel`:`Drive ${hud.truckName}`} onClick={toggleVehicle} disabled={!hud.driving&&hud.truckHp>0&&hud.truckFuel<=0}><span>{hud.driving?"↙":hud.truckName==="Mustang"&&!saveRef.current.vehicleKeyOwned?"⌁":"▰"}</span><small>{hud.driving?"EXIT":hud.truckName==="Mustang"&&!saveRef.current.vehicleKeyOwned?"LOCKED":hud.truckHp<=0?"REPAIR 50":hud.truckFuel<=0?"EMPTY":"DRIVE"}</small></button>}</div>
  <div className="action-slot context-slot">{!hud.driving&&hud.nearLanternMarket?<button className="lantern-market-button" aria-label="Open Night Lantern Market" onClick={()=>changeMode("lanternMarket")}><span>◇</span><small>TRADE</small></button>:!hud.driving&&hud.nearWorkbench?<button className="barricade-button wrench-button" aria-label="Take the pipe wrench from the farmhouse workbench" onClick={grabFarmhouseWrench}><span>⌕</span><small>WRENCH</small></button>:!hud.driving&&nearYarrow?<button className="yarrow-button" aria-label="Open Doc Yarrow's perk elixir cart" onClick={()=>changeMode("perkShop")}><span>Y</span><small>ELIXIRS</small></button>:!hud.driving&&nearBoxkeeper?<button className="boxkeeper-button" aria-label="Open the Boxkeeper mystery box" onClick={()=>changeMode("boxShop")}><span>?</span><small>BOX</small></button>:!hud.driving&&hud.nearBarricade&&hud.planks>0?<button className="barricade-button" aria-label="Board or reinforce nearby safehouse opening" onClick={boardBarricade}><span>▰</span><small>BOARD · {hud.planks}</small></button>:!hud.driving&&hud.nearCityLoot?<button className="locked-chest-button" aria-label={`Loot ${RUINED_LOOT_SITES.find(site=>site.id===hud.nearCityLoot)?.label??"ruins"}`} onClick={lootRuinedSite}><span>◇</span><small>LOOT</small></button>:hud.nearLockedChest?<button className="locked-chest-button" aria-label={`Use key on ${keyLabel(worldRef.current.chests.find(chest=>chest.id===hud.nearLockedChest)?.keyTier??"iron")} locked chest`} onClick={requestLockedChest}><span>▣</span><small>UNLOCK</small></button>:hospitalGeneratorNearby?<button className="fast-travel-button" aria-label="Power Saint Mercy generator with 15 vehicle fuel" onClick={powerHospitalGenerator}><span>⚡</span><small>POWER</small></button>:nearInteriorExit&&activeInterior?<button className="fast-travel-button" aria-label={`Exit ${activeInterior.label}`} onClick={exitInterior}><span>◇</span><small>EXIT</small></button>:nearbyInterior&&!hud.nearNpc?<button className="fast-travel-button" aria-label={`Enter ${nearbyInterior.label}`} onClick={()=>enterInterior(nearbyInterior.id)}><span>◇</span><small>ENTER</small></button>:nearDungeonExit?<button className="fast-travel-button" aria-label="Exit dungeon safely" onClick={exitDungeon}><span>◇</span><small>EXIT</small></button>:nearbyDungeonEntrance?<button className="fast-travel-button" aria-label={`Enter ${nearbyDungeonEntrance.name}`} onClick={()=>enterDungeon(nearbyDungeonEntrance.id)}><span>◇</span><small>ENTER</small></button>:!hud.driving&&hud.nearBase&&!hud.nearNpc?<button className="base-button" aria-label={`${baseState(saveRef.current,hud.nearBase).claimed?"Open":"Claim"} ${outpostById(hud.nearBase)?.name??"outpost"}`} onClick={claimOrOpenBase}><span>⚑</span><small>{baseState(saveRef.current,hud.nearBase).claimed?"BASE":"CLAIM"}</small></button>:!hud.driving&&hud.nearDog&&!hud.nearNpc?<button className="adopt-dog-button" aria-label="Adopt stray dog" onClick={adoptDog}><span>⌁</span><small>ADOPT</small></button>:!hud.driving&&hud.nearCampfire&&!hud.nearNpc?<button className="fast-travel-button" aria-label={`Travel to ${CAMPFIRES.find(fire=>fire.id===hud.nearCampfire)?.label??"linked campfire"}`} onClick={fastTravel}><span>△</span><small>{((["meadow","ember","meadowfrost","frostfall"] as CampfireId[]).includes(hud.nearCampfire)&&!saveRef.current.clearedRoomIds.includes(1))?"LOCKED":"TRAVEL"}</small></button>:!hud.driving&&hud.nearNpc?<button className="talk-button" aria-label={`Talk to ${NPCS.find(n=>n.id===hud.nearNpc)?.name??"villager"}`} onClick={talk}><span>…</span><small>TALK</small></button>:!hud.driving&&hud.nearTrunk?<button className="trunk-button" aria-label="Open storage trunk" onClick={openStorage}><span>▣</span><small>STASH</small></button>:!hud.driving&&saveRef.current.items.includes("Snare Trap")?<button className="locked-chest-button" aria-label="Deploy snare trap at closest threat" onClick={deploySnare}><span>⌄</span><small>TRAP</small></button>:null}</div>
  <div className="action-slot dash-slot"><button className="dash-button" aria-label="Dash" onClick={dash} disabled={hud.dash>0||hud.driving}><span>↗</span><small>{hud.dash>0?`${(hud.dash/1000).toFixed(1)}s`:"DASH"}</small></button></div>
  <div className="action-slot flask-slot"><button className="flask-button" aria-label={`Use healing item. ${hud.flasks+saveRef.current.healthPotions} remaining`} onClick={drinkFlask} disabled={hud.flasks+saveRef.current.healthPotions<=0||hud.hp>=hud.maxHp}><span>+</span><small>{hud.flasks+saveRef.current.healthPotions}</small></button></div>
  <div className="action-slot melee-slot">{!hud.driving&&<button className="melee-button" aria-label={saveRef.current.meleeWeaponName===MELEE_WEAPONS.chainsaw.name?"Hold to rev Chainsaw":"Swing "+saveRef.current.meleeWeaponName} onPointerDown={attackHoldDown} onPointerUp={attackHoldUp} onPointerCancel={attackHoldUp} onPointerLeave={attackHoldUp}><span>╱</span><small>{saveRef.current.meleeWeaponName===MELEE_WEAPONS.chainsaw.name?"REV":"MELEE"}</small></button>}{!hud.driving&&hud.gunName&&hud.gunName!==CROSSBOW_NAME&&<button className={`gun-ammo ${hud.reloading?"reloading":""}`} aria-label={hud.reloading?`${hud.gunName} reloading`:`Reload ${hud.gunName}, ${hud.gunMagazine} rounds in magazine and ${hud.gunReserve} reserve`} onClick={cycleAmmoType} onDoubleClick={reloadGun}><strong>{hud.gunMagazine}</strong><span>/ {hud.gunReserve}</span>{hud.reloading&&<i style={{width:`${Math.round(hud.reloadProgress*100)}%`}}/>}<small style={{color:AMMO_META[saveRef.current.selectedAmmoType].color}}>{hud.reloading?"RELOADING":`${AMMO_META[saveRef.current.selectedAmmoType].short} · ${saveRef.current.selectedAmmoType==="standard"?hud.gunReserve:elementalAmmoCount(saveRef.current)}`}</small></button>}{!hud.driving&&hud.gunName===CROSSBOW_NAME&&<button type="button" className={`bolt-ammo ${hud.boltCount===0?"empty":""}`} onClick={cycleAmmoType} aria-label={`Cycle ammo type. ${AMMO_META[saveRef.current.selectedAmmoType].name}, ${elementalAmmoCount(saveRef.current)} elemental rounds`}><span aria-hidden="true">➶</span><strong>{hud.boltCount}</strong><small style={{color:AMMO_META[saveRef.current.selectedAmmoType].color}}>{AMMO_META[saveRef.current.selectedAmmoType].short} · {saveRef.current.selectedAmmoType==="standard"?hud.boltCount:elementalAmmoCount(saveRef.current)}</small></button>}</div>
</div></div></>}
  {mode==="map"&&<FullWorldMap world={worldRef.current} boxLocation={mysteryBoxLocation(saveRef.current)} docLocation={yarrowLocation(saveRef.current)} onClose={()=>changeMode("playing")}/>} 
  {mode==="perkShop"&&<div className="overlay merchant-overlay perk-shop" role="dialog" aria-label="Doc Yarrow's perk elixir cart"><div className="perk-shop-head"><div><span>TRAVELING APOTHECARY</span><h2>Doc Yarrow</h2><small>{docLocation.name} · {hud.coins} gold · {hudPerks.length}/3 active</small></div><button type="button" aria-label="Close Doc Yarrow's cart" onClick={()=>changeMode("playing")}>×</button></div><div className="merchant-scroll">{PERK_ELIXIRS.map(perk=>{const count=perkCount(saveRef.current,perk.id),active=hudPerks.some(item=>item.active.id===perk.id),full=hudPerks.length>=3&&!active;return <section className="perk-shop-row" key={perk.id} style={{"--perk-color":perk.color} as CSSProperties}><div className="perk-vial" aria-hidden="true"><i/>{perk.glyph}</div><div className="perk-copy"><strong>{perk.name}</strong><span>{perk.detail}</span><small>{perk.durationMs?`${formatPerkTime(Math.round(perk.durationMs/1000))} active`:`Revive once · until down`} · carry {count}</small></div><div className="perk-actions"><button type="button" disabled={hud.coins<perk.cost||count>=9} onClick={()=>buyPerkElixir(perk.id)}>BUY <b>{perk.cost}</b></button><button type="button" className="drink" disabled={count<1||full} onClick={()=>drinkPerkElixir(perk.id)}>{active?"REFRESH":"DRINK"}</button></div></section>;})}</div><div className="perk-shop-foot"><span>Craft more at upgraded outpost cook fires.</span><b>Timed effects expire · Second Wind ends when used</b></div></div>}
