  {mode==="options"&&<div className="overlay options-overlay" role="dialog" aria-label="Gameplay options"><div className="options-heading"><div><p className="eyebrow">RUN PAUSED</p><h2>Options</h2></div><button type="button" aria-label="Back to pause menu" onClick={()=>changeMode("paused")}>‹ Back</button></div><div className="options-list"><button type="button" className="option-toggle" aria-pressed={gameplayOptions.screenShakeEnabled} onClick={()=>updateGameplayOptions({screenShakeEnabled:!gameplayOptions.screenShakeEnabled})}><span><b>Screen shake</b><small>Impacts and heavy attacks</small></span><i>{gameplayOptions.screenShakeEnabled?"ON":"OFF"}</i></button><button type="button" className="option-toggle" aria-pressed={gameplayOptions.damageNumbersEnabled} onClick={()=>updateGameplayOptions({damageNumbersEnabled:!gameplayOptions.damageNumbersEnabled})}><span><b>Damage numbers</b><small>Floating hit values</small></span><i>{gameplayOptions.damageNumbersEnabled?"ON":"OFF"}</i></button><button type="button" className="option-toggle" aria-pressed={gameplayOptions.ambientParticleDensity==="full"} onClick={()=>updateGameplayOptions({ambientParticleDensity:gameplayOptions.ambientParticleDensity==="full"?"reduced":"full"})}><span><b>Ambient particles</b><small>Weather, sparks and atmosphere</small></span><i>{gameplayOptions.ambientParticleDensity==="full"?"FULL":"REDUCED"}</i></button><div className="option-audio"><div><span><b>Zombie audio</b><small>Threat calls and combat sounds</small></span><button type="button" aria-label={muted?"Unmute all audio":"Mute all audio"} aria-pressed={muted} onClick={()=>setAudioMuted(!muted)}>{muted?"MUTED":"SOUND ON"}</button></div><label htmlFor="zombie-volume"><span>Volume</span><output>{Math.round(gameplayOptions.zombieAudioVolume*100)}%</output></label><input id="zombie-volume" aria-label="Zombie audio volume" type="range" min="0" max="100" step="5" value={Math.round(gameplayOptions.zombieAudioVolume*100)} onChange={event=>{const value=Number(event.currentTarget.value)/100;setGameplayOptions(current=>({...current,zombieAudioVolume:value}));saveRef.current={...saveRef.current,zombieAudioVolume:value};}} onPointerUp={()=>updateGameplayOptions({zombieAudioVolume:saveRef.current.zombieAudioVolume})} onKeyUp={()=>updateGameplayOptions({zombieAudioVolume:saveRef.current.zombieAudioVolume})}/></div><button type="button" className="option-toggle" aria-pressed={gameplayOptions.autoLootCommon} onClick={()=>updateGameplayOptions({autoLootCommon:!gameplayOptions.autoLootCommon})}><span><b>Auto-loot common items</b><small>Collect basics from farther away</small></span><i>{gameplayOptions.autoLootCommon?"ON":"OFF"}</i></button><div className="option-segment" role="group" aria-label="HUD rail auto-collapse delay"><span><b>HUD rail auto-collapse</b><small>Collapse after opening</small></span><div>{(["never","5s","15s"] as const).map(value=><button type="button" key={value} aria-pressed={gameplayOptions.hudRailAutoCollapse===value} className={gameplayOptions.hudRailAutoCollapse===value?"selected":""} onClick={()=>updateGameplayOptions({hudRailAutoCollapse:value})}>{value==="never"?"Never":value}</button>)}</div></div></div><button type="button" className="primary-button" onClick={()=>changeMode("paused")}>Done</button></div>}
  {mode==="inventory"&&<div className="overlay inventory-overlay" role="dialog" aria-label="Inventory"><div className="inventory-heading"><div><p className="eyebrow">TRAVELER'S PACK</p><h2>Inventory</h2></div><strong>{inventoryTab==="gear"?`${saveRef.current.items.length}/60`:`${saveRef.current.collectedRuleIds.length}/${SURVIVOR_RULES.length}`}</strong></div><nav className="inventory-tabs" aria-label="Inventory sections"><button className={inventoryTab==="gear"?"selected":""} aria-pressed={inventoryTab==="gear"} onClick={()=>setInventoryTab("gear")}>Gear</button><button className={inventoryTab==="rules"?"selected":""} aria-pressed={inventoryTab==="rules"} onClick={openRulesJournal}>Rules{unreadRuleCount>0&&<b aria-label={`${unreadRuleCount} unread rules`}>{unreadRuleCount}</b>}</button></nav>{inventoryTab==="gear"?<><div className="inventory-equipped"><section className="inventory-keyring" aria-label="Keyring"><span>KEYRING</span><div><b><i className="key-iron">Ⅰ</i>{saveRef.current.ironKeys}<small>Iron</small></b><b><i className="key-gold">Ⅱ</i>{saveRef.current.goldKeys}<small>Gold</small></b><b><i className="key-ancient">Ⅲ</i>{saveRef.current.ancientKeys}<small>Ancient</small></b></div></section><div className="cure-slot"><span>INFECTION CARE · {Math.round(saveRef.current.infectionLevel)}%</span><strong>{saveRef.current.antibiotics} antibiotics · {saveRef.current.antiseptic} antiseptic</strong><small>{saveRef.current.bandages} bandages · {saveRef.current.herbs} medicinal herbs</small><div className="cure-actions"><button disabled={saveRef.current.antibiotics<1||saveRef.current.infectionLevel<=0} onClick={()=>useCure("antibiotics")}>USE ANTIBIOTICS</button><button disabled={saveRef.current.antiseptic<1||saveRef.current.infectionLevel<=0} onClick={()=>useCure("antiseptic")}>USE ANTISEPTIC</button><button disabled={saveRef.current.bandages<1||saveRef.current.infectionLevel<=0} onClick={()=>useCure("bandages")}>USE BANDAGE</button></div></div><div><span>RANGED</span><strong style={{color:RARITY_COLOR[rarityForName(saveRef.current.weaponName,saveRef.current.rarity)]}}>{saveRef.current.weaponName}</strong><small>{Math.round(saveRef.current.weaponDamage)} damage</small></div><div className="melee-slot-card"><span>MELEE</span><strong style={{color:RARITY_COLOR[rarityForName(saveRef.current.meleeWeaponName)]}}>{saveRef.current.meleeWeaponName}</strong><small>{meleeSlotDetail(saveRef.current.meleeWeaponName)}</small></div><div className="relic-armor-slots"><span>RELIC ARMOR · {effectiveArmorDefense(saveRef.current)} DEF</span>{(["helm","cuirass","greaves"] as ArmorSlot[]).map(slot=>{const id=saveRef.current.equippedArmorPieces.find(pieceId=>isArmorPieceId(pieceId)&&ARMOR_PIECES[pieceId].slot===slot),piece=id&&isArmorPieceId(id)?ARMOR_PIECES[id]:null;return <small key={slot}><b>{slot}</b>{piece?.name??"Empty"}</small>;})}</div><div className="armor-set-progress"><span>SET BONUSES</span>{(["ember","frost","plague"] as ArmorSetId[]).map(set=>{const count=equippedSetCount(saveRef.current,set);return <small key={set} className={`set-${set}`}><b>{set.toUpperCase()} {count}/3</b><i>{set==="ember"?"2: burn attackers · 3: fire trail":set==="frost"?"2: slow attackers · 3: chill aura":"2: infection immune + bile resist · 3: corrosive touch"}</i></small>;})}</div><div><span>CHARM</span><strong>{saveRef.current.charmName}</strong><small>{Math.round(saveRef.current.critChance*100)}% crit</small></div><div className="trinket-slot"><span>TRINKET</span><strong style={{color:RARITY_COLOR[rarityForName(saveRef.current.trinketName)]}}>{saveRef.current.trinketName}</strong><small>{saveRef.current.trinketName==="None"?"Empty wearable slot":trinketByName(saveRef.current.trinketName)?.detail}</small></div><div className="throwable-slot"><span>THROWABLE</span><strong>{THROWABLE_LABELS[saveRef.current.selectedThrowable]} · {throwableCount(saveRef.current,saveRef.current.selectedThrowable)}</strong><small>{saveRef.current.pipeBombs} pipe · {saveRef.current.molotovs} fire · {saveRef.current.bileJars} bile</small><div className="throwable-select">{(["pipeBomb","molotov","bileJar"] as ThrowableKind[]).map(kind=><button key={kind} aria-label={`Equip ${THROWABLE_LABELS[kind]}`} aria-pressed={saveRef.current.selectedThrowable===kind} onClick={()=>selectThrowable(kind)}>{kind==="pipeBomb"?"PIPE":kind==="molotov"?"FIRE":"BILE"}</button>)}</div><div className="throwable-craft"><span>{saveRef.current.woodScraps} scrap · {saveRef.current.rags} rags</span>{(["pipeBomb","molotov","bileJar"] as ThrowableKind[]).map(kind=>{const cost=kind==="pipeBomb"?{s:3,r:1}:kind==="molotov"?{s:1,r:2}:{s:2,r:1};return <button key={kind} disabled={saveRef.current.woodScraps<cost.s||saveRef.current.rags<cost.r} onClick={()=>craftThrowable(kind)}>CRAFT {cost.s}+{cost.r}</button>;})}</div></div><div className="gadget-slot"><span>GADGET</span><strong style={{color:RARITY_COLOR[rarityForName(saveRef.current.gadgetName)]}}>{saveRef.current.gadgetName}</strong><small>{saveRef.current.gadgetName==="None"?"Empty utility slot":`${saveRef.current.flashlightOn?"On":"Off"} · ${flashlightByName(saveRef.current.gadgetName)?.detail}`}</small></div></div><div className="inventory-scroll">{saveRef.current.items.length===0?<div className="empty-pack"><strong>Your pack is empty.</strong><span>Bosses, region relics, and shops will fill it.</span></div>:<div className="inventory-grid" role="grid" aria-label="Pack items">{saveRef.current.items.map((item,index)=>{const rarity=rarityForName(item);return <button role="gridcell" aria-label={`${item}, ${rarity}`} aria-pressed={selectedInventoryIndex===index} className={`inventory-cell ${selectedInventoryIndex===index?"selected":""}`} key={`${item}-${index}`} onClick={()=>setSelectedInventoryIndex(index)} style={{color:RARITY_COLOR[rarity]}}><ItemIcon name={item}/><span>{rarity}</span></button>;})}</div>}</div>{selectedInventoryItem&&<div className="inventory-detail" aria-live="polite"><span style={{color:RARITY_COLOR[rarityForName(selectedInventoryItem)]}}>{rarityForName(selectedInventoryItem)} · {inventoryKind(selectedInventoryItem)}</span><strong>{selectedInventoryItem}</strong><small>{itemDetail(selectedInventoryItem)}</small>{selectedInventoryItem==="Snare Trap"?<button className="trinket-equip-button" onClick={deploySnare}>Deploy trap</button>:inventoryKind(selectedInventoryItem)==="trinket"?<button className="trinket-equip-button" onClick={()=>toggleTrinket(selectedInventoryItem)}>{saveRef.current.trinketName===selectedInventoryItem?"Unequip trinket":"Equip trinket"}</button>:inventoryKind(selectedInventoryItem)==="gadget"?<button className="trinket-equip-button" onClick={()=>toggleGadget(selectedInventoryItem)}>{saveRef.current.gadgetName===selectedInventoryItem?"Unequip gadget":"Equip gadget"}</button>:armorPieceByName(selectedInventoryItem)?<button className="trinket-equip-button" onClick={()=>toggleArmorPiece(selectedInventoryItem)}>{saveRef.current.equippedArmorPieces.includes(armorPieceByName(selectedInventoryItem)?.id??"")?"Unequip relic armor":"Equip relic armor"}</button>:<button className="trinket-equip-button" onClick={()=>equipInventoryItem(selectedInventoryItem)}>{(inventoryKind(selectedInventoryItem)==="weapon"?saveRef.current.weaponName:inventoryKind(selectedInventoryItem)==="melee"?saveRef.current.meleeWeaponName:inventoryKind(selectedInventoryItem)==="armor"?saveRef.current.armorName:saveRef.current.charmName)===selectedInventoryItem?"Equipped":"Equip"}</button>}</div>}<div className="inventory-footer"><span>{saveRef.current.headshots} headshots</span><span>{saveRef.current.headshotKills} headshot kills</span><span>{saveRef.current.bossesDefeated} bosses</span><span>{saveRef.current.chestsOpened} chests</span></div></>:<section className="rules-journal" aria-label="Collected survivor rules">{saveRef.current.collectedRuleIds.length===0?<div className="rules-empty"><strong>No rules recovered yet.</strong><span>Look for carved stone tablets in named regions.</span></div>:saveRef.current.collectedRuleIds.map(id=>{const rule=RULE_BY_ID.get(id as RuleId),tablet=RULE_TABLETS.find(entry=>entry.ruleId===id);return rule?<article key={rule.id}><b>#{rule.number}</b><div><strong>{rule.title}</strong><p>{rule.flavor}</p><small>Recovered in {tablet?.place??"the wilds"}</small></div></article>:null;})}<footer>{saveRef.current.collectedRuleIds.length} of {SURVIVOR_RULES.length} recovered</footer></section>}<button className="primary-button" onClick={()=>{setSelectedInventoryIndex(null);changeMode("playing");}}>Return to the world</button></div>}
  {mode==="storage"&&<div className="overlay storage-overlay" role="dialog" aria-label="House storage trunk"><div className="inventory-heading"><div><p className="eyebrow">YOUR HOUSE</p><h2>Storage trunk</h2></div><strong>{saveRef.current.storedItems.length}/60</strong></div><div className="storage-columns"><section><h3>Pack</h3>{saveRef.current.items.length===0?<p className="storage-empty">Nothing to store.</p>:saveRef.current.items.map((item,index)=><button key={`pack-${item}-${index}`} className="storage-item" onClick={()=>storeItem(index)}><span>{item}</span><b>STASH →</b></button>)}</section><section><h3>Trunk</h3>{saveRef.current.storedItems.length===0?<p className="storage-empty">The trunk is empty.</p>:saveRef.current.storedItems.map((item,index)=><button key={`stored-${item}-${index}`} className="storage-item" onClick={()=>retrieveItem(index)}><span>{item}</span><b>← TAKE</b></button>)}</section></div><p className="storage-note">Active gear stays equipped while its item is stored.</p><button className="primary-button" onClick={()=>changeMode("playing")}>Close trunk</button></div>}
  {mode==="vehicleStorage"&&<div className="overlay storage-overlay vehicle-storage-overlay" role="dialog" aria-label={`${hud.truckName} inventory`}><div className="inventory-heading"><div><p className="eyebrow">{hud.truckName.toUpperCase()}</p><h2>Vehicle inventory</h2></div><strong>{vehicleCargo.length}/4</strong></div><div className="storage-columns vehicle-storage-columns"><section><h3>Pack</h3>{saveRef.current.items.length===0?<p className="storage-empty">Nothing to stow.</p>:vehicleCargo.length>=4?<p className="storage-empty">Cargo is full. Take something out first.</p>:saveRef.current.items.map((item,index)=><button key={`cargo-pack-${item}-${index}`} className="storage-item cargo-item" onClick={()=>storeInVehicle(index)}><ItemIcon name={item}/><span>{item}</span><b>STOW →</b></button>)}</section><section><h3>Cargo · 4 slots</h3><div className="vehicle-cargo-grid" role="grid" aria-label={`${hud.truckName} cargo slots`}>{Array.from({length:4},(_,index)=>{const item=vehicleCargo[index];return item?<button role="gridcell" key={`vehicle-cargo-${item}-${index}`} className="vehicle-cargo-slot filled" aria-label={`Take ${item} from cargo`} onClick={()=>retrieveFromVehicle(index)}><ItemIcon name={item}/><span>{item}</span><b>TAKE</b></button>:<div role="gridcell" aria-label={`Empty cargo slot ${index+1}`} key={`vehicle-cargo-empty-${index}`} className="vehicle-cargo-slot"><span>{index+1}</span><small>EMPTY</small></div>;})}</div></section></div><p className="storage-note">Each vehicle keeps its own four cargo slots. Active gear stays equipped while stowed.</p><button className="primary-button" onClick={()=>changeMode("playing")}>Close cargo</button></div>}
  {mode==="baseBuild"&&activeOutpostUi&&activeBaseState&&<div className="overlay base-overlay" role="dialog" aria-label={`${activeOutpostUi.name} base menu`}><div className="base-heading"><div><p className="eyebrow">CLAIMED OUTPOST</p><h2>{activeOutpostUi.name}</h2></div><strong>{hud.coins} GOLD</strong></div><div className="base-actions"><button className="holdout-launch" onClick={()=>startHoldout(activeOutpostUi.id)}><span>⚔</span><strong>Hold the Line</strong><small>10 waves · best {holdoutBestWave(saveRef.current,activeOutpostUi.id)}/10 · {holdoutCompletionCount(saveRef.current,activeOutpostUi.id)} clears</small></button><button onClick={restAtBase}><span>▲</span><strong>Rest at campfire</strong><small>Heal fully, restore flasks, set respawn here</small></button><button onClick={openBaseStash}><span>▣</span><strong>Shared storage trunk</strong><small>{saveRef.current.storedItems.length} items · linked to village house</small></button></div><section className="build-bench"><header><div><span>BUILD BENCH</span><strong>Outpost upgrades</strong></div><small>{activeBaseState.upgrades.length}/3 built</small></header>{BASE_UPGRADES.map(upgrade=>{const owned=activeBaseState.upgrades.includes(upgrade.id);return <button key={upgrade.id} disabled={owned||hud.coins<upgrade.cost} onClick={()=>buyBaseUpgrade(upgrade.id)}><span><strong>{upgrade.name}</strong><small>{upgrade.detail}</small></span><b>{owned?"BUILT":`${upgrade.cost} ◉`}</b></button>;})}</section><section className="gadget-bench combo-bench" aria-label="Combo weapon workbench"><header><div><span>COMBO BENCH</span><strong>Pick two ingredients</strong></div><small>{comboIngredients.length}/2 selected</small></header>{COMBO_RECIPES.map(recipe=><div className="combo-recipe" key={recipe.id}><div className="combo-copy"><strong style={{color:RARITY_COLOR[recipe.rarity]}}>{recipe.name}</strong><small>{recipe.detail}</small></div><div className="combo-picks">{recipe.ingredients.map(ingredient=><button key={ingredient} aria-pressed={comboIngredients.includes(ingredient)} className={comboIngredients.includes(ingredient)?"selected":""} disabled={!comboIngredientAvailable(ingredient)} onClick={()=>toggleComboIngredient(ingredient)}><span>{ingredient}</span><small>{comboIngredientAvailable(ingredient)?"READY":"MISSING"}</small></button>)}</div></div>)}<button className="combo-action" disabled={comboIngredients.length!==2||!COMBO_RECIPES.some(recipe=>recipe.ingredients.every(ingredient=>comboIngredients.includes(ingredient))&&recipe.ingredients.every(comboIngredientAvailable))} onClick={craftCombo}>COMBINE WEAPON</button><small className="combo-note">Hardware parts drop from opened chests. Oil-soaked cloth uses 1 rag + Lamp Oil. Scrap costs 2 wood scraps.</small></section><section className="gadget-bench"><header><div><span>FIELD CRAFT</span><strong>Basic Flashlight</strong></div><small>Night gear</small></header><button disabled={ownsOrHasPendingGadget(saveRef.current,"basic")||hud.coins<30} onClick={craftBasicFlashlight}><span><strong>Craft Basic Flashlight</strong><small>Focused night beam · briefly slows exposed zombies</small></span><b>{ownsOrHasPendingGadget(saveRef.current,"basic")?"OWNED":"30 ◉"}</b></button><button disabled={saveRef.current.uvEmitterOwned||saveRef.current.volatileEyes<UV_EMITTER_EYE_COST||hud.woodScraps<UV_EMITTER_SCRAP_COST} onClick={craftUvEmitter}><span><strong>Craft UV Emitter</strong><small>Violet beam burns zombies · stronger against Night Volatiles</small></span><b>{saveRef.current.uvEmitterOwned?"OWNED":`${UV_EMITTER_EYE_COST} EYES + ${UV_EMITTER_SCRAP_COST} SCRAP`}</b></button><button disabled={hud.woodScraps<2} onClick={craftBolts}><span><strong>Craft 4 crossbow bolts</strong><small>{hud.woodScraps} wood scraps · silent ammunition</small></span><b>2 SCRAP</b></button>{(["incendiary","frost","shock"] as const).map(type=><button key={type} disabled={hud.woodScraps<3||saveRef.current.specialTrophies.length<1} onClick={()=>craftElementalAmmo(type)}><span><strong style={{color:AMMO_META[type].color}}>Craft {AMMO_META[type].name}</strong><small>18 rounds · {hud.woodScraps} scrap · {saveRef.current.specialTrophies.length} boss/special components</small></span><b>3 SCRAP + 1 TROPHY</b></button>)}<button disabled={hud.woodScraps<2} onClick={craftPlanks}><span><strong>Cut 2 barricade planks</strong><small>{hud.woodScraps} wood scraps · 50 HP per plank</small></span><b>2 SCRAP</b></button></section>{activeBaseState.upgrades.includes("cookfire")&&<div className="cook-row"><span><strong>Cook fire</strong><small>{saveRef.current.rawMeat} raw meat · {saveRef.current.cookedMeals} meals · {saveRef.current.herbs} herbs</small></span><button onClick={cookMeal} disabled={saveRef.current.rawMeat<2}>Cook 2 meat</button><button onClick={craftAntiseptic} disabled={saveRef.current.herbs<2}>Craft antiseptic · 2 herbs</button><button onClick={craftPlanks} disabled={hud.woodScraps<2}>Cut planks</button><button onClick={eatMeal} disabled={saveRef.current.cookedMeals<1||hud.hp>=hud.maxHp}>Eat +50</button><div className="cook-perks"><strong>PERK ELIXIRS</strong>{PERK_ELIXIRS.map(perk=><button key={perk.id} type="button" disabled={saveRef.current.herbs<perk.herbCost||saveRef.current.woodScraps<perk.scrapCost||perkCount(saveRef.current,perk.id)>=9} onClick={()=>craftPerkElixir(perk.id)} style={{"--perk-color":perk.color} as CSSProperties}><span>{perk.glyph} {perk.name}</span><small>{perk.herbCost} herbs · {perk.scrapCost} scrap</small></button>)}</div></div>}<button className="primary-button" onClick={()=>changeMode("playing")}>Return to outpost</button></div>}
  {mode==="loot"&&<div className="overlay loot-overlay"><p className="eyebrow">REGION CLEARED</p><h2>Choose one relic.</h2><div className="loot-list">{loot.map(choice=><button key={choice.id} className="loot-choice" onClick={()=>chooseLoot(choice)}><span className="loot-icon" style={{color:RARITY_COLOR[choice.rarity]}}>{choice.icon}</span><span><strong>{choice.name}</strong><small style={{color:RARITY_COLOR[choice.rarity]}}>{choice.rarity}</small><em>{choice.detail}</em></span><b>TAKE</b></button>)}</div></div>}
